<?php require '../includes/functions.php';check_csrf();try{$name=field('name',100);$email=field('email',190);$msg=field('message',3000);if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new Exception('Enter a valid email address.');if(time()-($_SESSION['last_message']??0)<30)throw new Exception('Please wait 30 seconds before sending another message.');query('INSERT INTO messages(name,email,message) VALUES(?,?,?)',[$name,$email,$msg]);$_SESSION['last_message']=time();flash('Your message has been saved for the admin. Thank you!');}catch(Exception $e){flash($e instanceof PDOException?'Unable to send message.':$e->getMessage(),'error');}go('contact.php');